    @Test func compressed() {
        let mismatches = Mismatches("portCompressedU16InVectorCode")
        let aInputs = Inputs.vectors(H.self, seed: 0x8993_2CEF_0B70_A652)
        let maskInputs = Inputs.masks(H.Mask.self, seed: 0x8993_2DEF_0B70_A805)
        for (a, mask) in everyPair(aInputs, maskInputs) {
            let port = { () -> SIMD<UInt16> in
                var a = a
                var mask = mask
                return withUnsafeTemporaryAllocation(of: SIMD<UInt16>.self, capacity: 1) { result in
                    unsafe portCompressedU16InVectorCode(
                        result.baseAddress.unsafelyUnwrapped,
                        &a,
                        where: &mask
                    )
                    return unsafe result.baseAddress.unsafelyUnwrapped.move()
                }
            }()
            let reference = { () -> SIMD<UInt16> in
                var a = a
                var mask = mask
                return withUnsafeTemporaryAllocation(of: SIMD<UInt16>.self, capacity: 1) { result in
                    unsafe highwayCompressedU16InVectorCode(
                        result.baseAddress.unsafelyUnwrapped,
                        &a,
                        where: &mask
                    )
                    return unsafe result.baseAddress.unsafelyUnwrapped.move()
                }
            }()
            let checkedLanes =
                HighwayReference.compressTailIsDeterministicU16() ? H.laneCount : H.trueCount(mask)
            mismatches.check(
                (0..<checkedLanes).map { port.simd[$0] },
                (0..<checkedLanes).map { reference.simd[$0] },
                "a: \(describe(a)), mask: \(describe(mask))"
            )
        }
        mismatches.record()
    }

